import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 25 · Christmas recipe: peppermint bark (Google Trends 3/11: christmas bark, peppermint rising)
# Grandma Ruth: born 1944 in Mansfield, Ohio; mother Dorothy, father Walter, brother Danny, Grandma Pearl.

sc("""Sweetheart, last December my granddaughter paid thirty-two dollars for one little tin of peppermint bark at the mall. Thirty-two dollars. She brought it to my house so proud, and I opened it, and the white layer slid right off the chocolate like a loose shingle. I said, honey, give me five dollars and an hour, and I'll make you a better one that never comes apart.""",
   "peppermint bark Christmas tin", "THIRTY-TWO DOLLARS")
sc("""So tonight I'm giving you my peppermint bark. A dark chocolate layer, a white chocolate layer, crushed candy canes on top, and the two layers stuck together like they were born that way. Every ingredient, every step, and the three mistakes that make the layers separate. It's the easiest Christmas candy you will ever make, and it's the one people ask for every year. And stay with me, because the step that keeps the layers together is one almost nobody does, and I'll show you exactly when to do it.""",
   "peppermint bark pieces plate", "NEVER COMES APART")

ch("Candy canes in our house")
sc("""When I was a girl in Mansfield, candy canes came in a little cardboard box of twelve from the five and dime, and they were all white with red stripes and nothing else. My mother hung them on the tree with the hook end over the branch. And every one that broke, and they always broke, went into a jar in the pantry. By Christmas Eve, that jar was full of red and white pieces.""",
   "vintage candy canes Christmas tree", "THE JAR OF BROKEN ONES")
sc("""And on Christmas Eve afternoon, my mother melted a bar of chocolate in a bowl over the pot, poured it thin on a buttered pan, and threw the broken candy canes on top. She called it peppermint scrap. Danny and I broke it into pieces with a butter knife. It was nothing fancy. But that is the grandmother of every fancy tin of peppermint bark you see in the stores today.""",
   "melted chocolate pan vintage kitchen", "PEPPERMINT SCRAP")
sc("""The white layer came later. In nineteen seventy-one, my sister-in-law brought a version with white chocolate on top, and my mother tasted it and said, well, now that's just showing off. Then she asked for the recipe before the evening was over. That's the version I've made every year since, and I've changed only one thing. The thing that keeps the layers together.""",
   "1970s family Christmas party kitchen", "THAT'S JUST SHOWING OFF")

ch("What you need")
sc("""Here's what you need, honey. Twelve ounces of good semi-sweet or dark chocolate, chopped. Twelve ounces of white chocolate, chopped. Two teaspoons of vegetable oil or coconut oil, one for each layer. Half a teaspoon of peppermint extract. And about eight regular candy canes, or a cup of crushed peppermint candies. That's the whole list. Five things.""",
   "chopped chocolate cutting board", "FIVE THINGS")
sc("""Now listen about the chocolate, because this matters. Buy real chocolate bars, the kind that say cocoa butter on the label. Not chocolate chips. Chips have something added so they hold their shape in cookies, and that means they don't melt smooth and they don't set with a snap. And not those colored candy melts either. They taste like sweet wax.""",
   "chocolate bars baking aisle", "BARS, NOT CHIPS")
sc("""And the white chocolate is the fussy one. Look for cocoa butter in the ingredients. If the label says white baking chips or vanilla coating, it isn't really white chocolate, and it won't stick to the dark layer the same way. This is where people save a dollar and then wonder why their bark falls apart in the tin. In a minute I'll show you the one moment that decides whether your layers stick.""",
   "white chocolate bar label", "LOOK FOR COCOA BUTTER")
sc("""You need an eight by eight pan for thick bark, or a nine by thirteen for thinner pieces. Line it with parchment or wax paper, and let the paper hang over two sides, so you can lift the whole slab out when it's done. My mother used a buttered pan, and we had to pry the bark out with a spatula. Parchment is one of the few new things I'll admit is better.""",
   "parchment lined baking pan", "LET THE PAPER HANG OVER")

ch("Step by step")
sc("""Step one. Crush the candy canes. Put them in a zip bag, wrap the bag in a dish towel, and tap it with a rolling pin or the bottom of a heavy pot. Not too fine. You want little pieces like gravel, not dust. Then shake them in a strainer to get the powder out. Save the powder for your cocoa. The powder makes the top of the bark sticky.""",
   "crushing candy canes rolling pin bag", "LIKE GRAVEL, NOT DUST")
sc("""Step two. Melt the dark chocolate with one teaspoon of oil. The easy way is in the microwave, in a glass bowl, thirty seconds at a time, stirring well every time, even when it doesn't look like it's melting yet. Stop when there are still a few little lumps, and just stir until they disappear. If you overheat chocolate, it turns thick and grainy, and you can't fix it. If this is helping you, honey, tap the like button for me. It helps Grandma more than you know.""",
   "melting chocolate glass bowl stirring", "THIRTY SECONDS AT A TIME")
sc("""Or do it my mother's way. A bowl sitting on top of a small pot with an inch of barely simmering water. The bowl must not touch the water, and not one drop of water can get into the chocolate. One drop of water and the whole bowl seizes into a stiff, dull paste. My mother wiped the bottom of the bowl with a towel every time she lifted it.""",
   "double boiler chocolate stove", "NOT ONE DROP OF WATER")
sc("""Step three. Stir a quarter teaspoon of the peppermint extract into the dark chocolate and pour it into the lined pan. Spread it even with the back of a spoon or a spatula, right into the corners. Then tap the pan on the counter a few times to settle it flat and pop the bubbles.""",
   "spreading chocolate pan spatula", "TAP THE PAN")
sc("""Step four, and this is the secret, sweetheart. Put the pan in the icebox for only fifteen to twenty minutes. Not an hour. You want the dark layer set enough that it doesn't swirl when you pour on the next layer, but still a little soft and tacky when you touch it. Touch the corner. If it leaves a faint fingerprint, it's ready.""",
   "chocolate layer refrigerator timer", "STILL A LITTLE TACKY")
sc("""This is why store bark and so much homemade bark comes apart. If the dark layer gets cold and hard, the warm white layer just sits on top of it like a blanket on a bed. They never join. But when the bottom is still a little soft, the two chocolates melt together right where they meet, and they set as one piece. Stay with me, because the next step has to happen fast.""",
   "chocolate bark two layers close up", "LIKE A BLANKET")
sc("""Step five. While the dark layer chills, melt the white chocolate with the other teaspoon of oil, the same way, but gentler. Twenty seconds at a time, because white chocolate burns faster than dark. Stir in the last quarter teaspoon of peppermint extract. It should be smooth and pourable, and only just warm. If it's hot, let it sit a few minutes.""",
   "melted white chocolate bowl", "GENTLER WITH THE WHITE")
sc("""Step six. Pour the white chocolate over the tacky dark layer, and spread it quickly and gently all the way to the edges. Then right away, before it sets, scatter the crushed candy canes all over the top and press them down lightly with your palm, so they stick. If you wait even five minutes, they'll just roll off when you cut it.""",
   "sprinkling crushed candy cane white chocolate", "PRESS THEM DOWN")
sc("""Step seven. Back in the icebox for about an hour, until it's completely firm. Then lift the whole slab out by the paper, and let it sit on the counter for ten minutes so it doesn't crack into slivers. Break it into rough pieces with your hands, or cut it with a big knife warmed under hot water and wiped dry. Warm knife, clean cuts.""",
   "cutting peppermint bark knife board", "WARM KNIFE, CLEAN CUTS")

ch("Three mistakes")
sc("""So the three mistakes, honey. Mistake one, the dark layer gets too cold before the white goes on. Fifteen to twenty minutes, not an hour, not overnight. Mistake two, chocolate chips or candy melts instead of real chocolate bars. And mistake three, overheating the chocolate. Short bursts, stir every time, and take it off before it's all melted. But there's one more, and you'll see why my husband laughed.""",
   "chocolate bark cracked layers", "THREE MISTAKES")
sc("""And here's one more, a little one. Don't add the peppermint extract to chocolate that's too hot, and never use a water-based flavoring. Use oil-based or regular peppermint extract, just a little. One year I used a whole teaspoon in each layer, and my husband said it tasted like toothpaste. He was right. Half a teaspoon total is plenty.""",
   "peppermint extract bottle spoon", "IT TASTED LIKE TOOTHPASTE")

ch("Christmas gifts")
sc("""Now, why I love this one. A batch costs about five dollars and fills four little tins. Put the pieces in a cellophane bag tied with red ribbon, or in a jar with wax paper. For the mailman, the teachers, the neighbor, the lady at church. I give away twelve bags every year, and every December somebody stops me in the grocery store to ask if the bark is coming.""",
   "peppermint bark gift bags ribbon", "TWELVE BAGS A YEAR")
sc("""Keep it in a tin in a cool spot, or in the icebox if your house is warm. It keeps two or three weeks. Put wax paper between the layers so the pieces don't stick together. And keep it away from the cookies. Peppermint makes everything in the tin taste like peppermint, and nobody wants a peppermint gingerbread man.""",
   "cookie tin wax paper layers candy", "AWAY FROM THE COOKIES")
sc("""And for the children, honey, let them do the crushing. Give them the bag wrapped in a towel and a wooden spoon, and let them whack it on the kitchen floor. They'll feel like they made the whole thing. My grandson did the crushing every year from age four, and now he's twenty-six and he still calls me in December to ask if I need my candy canes crushed.""",
   "child crushing candy wooden spoon kitchen", "THEY MADE IT")

ch("Grandma's kitchen")
sc("""So one more time. Real chocolate bars, not chips. Melt it gently, thirty seconds at a time. Dark layer in the icebox only fifteen or twenty minutes, until it's set but still tacky. White chocolate on top, candy canes pressed in right away, then an hour to set. Warm knife. That's how you make peppermint bark that never comes apart, for five dollars instead of thirty-two.""",
   "peppermint bark pieces Christmas table", "FIVE DOLLARS, NOT THIRTY-TWO")
sc("""Tell me in the comments, sweetheart. Who in your family made the Christmas candy? Fudge, divinity, peanut brittle, bark? I bet I can guess what your grandmother made. Every day I'm bringing you another Christmas recipe from my kitchen. And if you want another one tonight, the whole playlist of Grandma's recipes is right there on your screen, and I'll see you in the next video. Good night, honey. Merry Christmas.""",
   "Christmas candy plate warm kitchen", "WHO MADE YOUR CHRISTMAS CANDY?")

for s in S:
    s["cuts"], s["moves"] = 4, True

save("grandma25", "Peppermint Bark That NEVER Separates (Make It for $5, Not $32)",
     ["Grandma Ruth is a narrated character built from real memories and records of the era.",
      "Recipe as written by Grandma Ruth: 12 oz semi-sweet or dark chocolate, 12 oz white chocolate, 2 tsp oil, 1/2 tsp peppermint extract, about 8 candy canes crushed; dark layer chilled 15 to 20 minutes before the white layer; set about 1 hour.",
      "Chocolate chips contain stabilizers so they hold their shape when baked; water causes melted chocolate to seize."],
     "christmas recipe", minutes=(10, 14.5), voice="en_US-lessac-high")
